    // `[ecx + 2*codeX + 0x848]` and reads the function-key band with
    // `movsx ...word ptr`, everything else with the low byte only.
    // The 0x848..0x947 span is unchanged.
    short scanCodeTable[128];
    int keyboardInstalled;
    int keyboardFilter;
    int keyCodeType;
    int extendFlag;
    int currWidgetID;
    int prevDialog;

    inputManager();
    message GetEvent();
    void Flush();
    void ForceMouseMove();
